{
  "name": "GhibliTrip AI",
  "description": "An AI-powered travel planner that generates detailed itineraries and Studio Ghibli-style illustrated maps."
}

export interface TripFormData {
  destination: string;
  days: number;
  travelers: number;
  startDate: string;
  interests: string;
  foodPreferences: string;
  accommodation: string;
  transportation: string;
}

export interface Activity {
  time: string;
  activity: string;
  description: string;
  location: string;
  costEstimate?: string;
}

export interface DayPlan {
  day: number;
  theme: string;
  activities: Activity[];
}

export interface ItineraryResult {
  title: string;
  summary: string;
  days: DayPlan[];
}

export enum AppState {
  INPUT = 'INPUT',
  GENERATING = 'GENERATING',
  RESULT = 'RESULT',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { TripFormData, ItineraryResult } from "../types";

// Initialize the client. 
// NOTE: Process.env.API_KEY is handled by the runtime environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates the text-based itinerary using Gemini 3 Pro.
 */
export const generateItinerary = async (formData: TripFormData): Promise<ItineraryResult> => {
  const prompt = `
    Create a detailed travel itinerary for a trip to ${formData.destination}.

    Details:
    - Duration: ${formData.days} days
    - Travelers: ${formData.travelers} people
    - Date: Starting ${formData.startDate}
    - Interests/Attractions: ${formData.interests}
    - Food Preferences: ${formData.foodPreferences}
    - Accommodation Style: ${formData.accommodation}
    - Transportation Preference: ${formData.transportation}

    Please provide a structured response with a catchy title, a brief summary, and a day-by-day breakdown including times, specific locations, and descriptions.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "A creative title for the trip" },
          summary: { type: Type.STRING, description: "A short, exciting summary of the trip vibe" },
          days: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.INTEGER },
                theme: { type: Type.STRING, description: "Theme of the day (e.g., Historical Walk)" },
                activities: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING, description: "e.g., 09:00 AM" },
                      activity: { type: Type.STRING, description: "Name of the activity or place" },
                      description: { type: Type.STRING, description: "What to do there, practical tips" },
                      location: { type: Type.STRING, description: "Specific location or area" },
                      costEstimate: { type: Type.STRING, description: "Estimated cost per person" }
                    },
                    required: ["time", "activity", "description", "location"]
                  }
                }
              },
              required: ["day", "theme", "activities"]
            }
          }
        },
        required: ["title", "summary", "days"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No itinerary generated.");

  return JSON.parse(text) as ItineraryResult;
};

/**
 * Generates a Studio Ghibli style map using Gemini 3 Pro Image.
 */
export const generateGhibliMap = async (destination: string, summary: string): Promise<string> => {
  const imagePrompt = `
    A breathtaking, hand-drawn illustrated travel map of ${destination} in the art style of Studio Ghibli backgrounds.

    Art Style Details:
    - Kazuo Oga style background art.
    - Watercolor and gouache textures.
    - Vibrant, lush greens, fluffy large cumulus clouds in a deep blue summer sky.
    - Whimsical, cozy, nostalgic atmosphere.
    - Soft lighting with blooming highlights.

    Content:
    - An overview map of ${destination}.
    - Cute miniature representations of key landmarks mentioned: ${summary.substring(0, 100)}...
    - Tiny trains, buses, or boats moving along routes.
    - High resolution, detailed, 4k.
    - No text or labels, just art.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { text: imagePrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9",
        imageSize: "2K"
      }
    }
  });

  // Extract the image from the response parts
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image generated.");
};

import React from 'react';
import { ItineraryResult, DayPlan, Activity } from '../types';
import { MapPin, Clock, Info, Download, ArrowLeft, RefreshCw } from 'lucide-react';

interface ItineraryDisplayProps {
  itinerary: ItineraryResult;
  mapUrl: string | null;
  onReset: () => void;
  isMapLoading: boolean;
}

