      const link = document.createElement('a');
      link.href = mapUrl;
      link.download = `Ghibli_Map_${itinerary.title.replace(/\s+/g, '_')}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto space-y-8 pb-12 animate-fade-in-up">

      {/* Header Actions */}
      <div className="flex justify-between items-center bg-white/80 backdrop-blur rounded-2xl p-4 shadow-sm">
        <button onClick={onReset} className="flex items-center text-gray-600 hover:text-emerald-600 font-semibold transition-colors">
          <ArrowLeft className="w-5 h-5 mr-2" />
          重新規劃
