        <h1 className="text-xl md:text-2xl font-bold text-gray-800 hidden md:block">{itinerary.title}</h1>
         <div className="w-24"></div> {/* Spacer for balance */}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Left Column: Itinerary */}
        <div className="space-y-6">
          <div className="bg-white/90 rounded-3xl p-6 shadow-lg border border-emerald-50">
            <h2 className="text-2xl font-bold text-gray-800 mb-2">{itinerary.title}</h2>
            <p className="text-gray-600 italic leading-relaxed">{itinerary.summary}</p>
          </div>

          <div className="space-y-6">
            {itinerary.days.map((day: DayPlan) => (
              <div key={day.day} className="bg-white/90 rounded-3xl overflow-hidden shadow-md hover:shadow-xl transition-shadow border-l-8 border-emerald-400">
                <div className="bg-emerald-50 p-4 border-b border-emerald-100 flex justify-between items-center">
                  <h3 className="font-bold text-emerald-800 text-lg">Day {day.day}</h3>
                  <span className="text-sm font-medium text-emerald-600 bg-white px-3 py-1 rounded-full border border-emerald-200">
                    {day.theme}
                  </span>
                </div>
                <div className="p-4 md:p-6 space-y-6 relative">
                  {/* Timeline Line */}
                  <div className="absolute left-6 md:left-8 top-6 bottom-6 w-0.5 bg-gray-200"></div>

                  {day.activities.map((act: Activity, idx) => (
                    <div key={idx} className="relative pl-8 md:pl-10">
                      {/* Timeline Dot */}
                      <div className="absolute left-0.5 md:left-2.5 top-1.5 w-3 h-3 rounded-full bg-emerald-400 ring-4 ring-white"></div>

                      <div className="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3 mb-1">
