import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import HeroInput from './components/HeroInput';
import ItineraryDisplay from './components/ItineraryDisplay';
import { generateItinerary, generateGhibliMap } from './services/geminiService';
import { TripFormData, ItineraryResult, AppState } from './types';
import { CloudSun } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.INPUT);
  const [itinerary, setItinerary] = useState<ItineraryResult | null>(null);
  const [mapUrl, setMapUrl] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isMapLoading, setIsMapLoading] = useState(false);

  const handleFormSubmit = async (data: TripFormData) => {
    setAppState(AppState.GENERATING);
    setErrorMsg(null);
    setItinerary(null);
    setMapUrl(null);

    try {
      // Step 1: Generate Text Itinerary
      const result = await generateItinerary(data);
      setItinerary(result);
      setAppState(AppState.RESULT);

      // Step 2: Start Map Generation (Parallel-ish: start after text to ensure context, but don't block text display)
      setIsMapLoading(true);
      try {
        const generatedMap = await generateGhibliMap(data.destination, result.summary);
        setMapUrl(generatedMap);
      } catch (mapErr) {
        console.error("Map generation failed", mapErr);
        // We don't fail the whole app if map fails, just show no map
      } finally {
        setIsMapLoading(false);
      }

    } catch (err: any) {
      console.error("Itinerary generation failed", err);
      setErrorMsg(err.message || "發生錯誤，請稍後再試。");
      setAppState(AppState.ERROR);
    }
  };

  const resetApp = () => {
    setAppState(AppState.INPUT);
    setItinerary(null);
    setMapUrl(null);
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen bg-[#f0f9f6] text-gray-800 font-sans selection:bg-emerald-200 selection:text-emerald-900">

      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
        {/* Sky Gradient */}
        <div className="absolute inset-0 bg-gradient-to-b from-blue-100 via-emerald-50 to-[#f0f9f6]"></div>
        {/* Clouds (Pure CSS shapes for simplicity) */}
        <div className="absolute top-[10%] left-[5%] w-64 h-24 bg-white opacity-40 rounded-full blur-2xl animate-pulse"></div>
        <div className="absolute top-[20%] right-[10%] w-96 h-32 bg-white opacity-30 rounded-full blur-3xl animate-pulse delay-1000"></div>
      </div>

      <div className="relative z-10 container mx-auto px-4 py-8 md:py-12">
        {/* Header Logo */}
        <header className="flex justify-center mb-12">
          <div className="flex items-center gap-3 cursor-pointer" onClick={resetApp}>
            <div className="bg-emerald-500 p-2 rounded-xl shadow-lg rotate-3 hover:rotate-6 transition-transform">
              <CloudSun className="w-8 h-8 text-white" />
            </div>
            <div>
              <h1 className="text-3xl font-black tracking-tight text-emerald-800 font-serif">GhibliTrip</h1>
              <p className="text-xs text-emerald-600 font-medium tracking-widest uppercase">AI Travel Planner</p>
            </div>
          </div>
        </header>

        <main className="w-full">
          {appState === AppState.INPUT && (
            <div className="animate-fade-in-up">
              <div className="text-center mb-10 max-w-2xl mx-auto">
                <h2 className="text-4xl md:text-5xl font-bold text-gray-800 mb-4 font-serif leading-tight">
                  <span className="text-emerald-600">夢想</span> 旅程<br/>從這裡開始
                </h2>
                <p className="text-lg text-gray-600">
                  輸入您的旅遊計畫，讓 AI 為您編織一段充滿魔法的旅程，並繪製獨一無二的吉卜力風格地圖。
                </p>
              </div>
              <HeroInput onSubmit={handleFormSubmit} isLoading={false} />
            </div>
          )}

          {appState === AppState.GENERATING && (
            <div className="flex flex-col items-center justify-center min-h-[50vh] animate-fade-in">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-emerald-200 border-t-emerald-500 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <CloudSun className="w-10 h-10 text-emerald-500 animate-bounce" />
                </div>
              </div>
              <h3 className="text-2xl font-bold text-emerald-800 mt-8">正在施展魔法...</h3>
              <p className="text-gray-500 mt-2">正在規劃最佳路線與繪製風景...</p>
            </div>
          )}

          {appState === AppState.RESULT && itinerary && (
            <ItineraryDisplay 
              itinerary={itinerary} 
              mapUrl={mapUrl} 
              onReset={resetApp}
              isMapLoading={isMapLoading}
            />
          )}

          {appState === AppState.ERROR && (
            <div className="max-w-md mx-auto bg-white p-8 rounded-3xl shadow-xl text-center border-l-8 border-red-400">
              <div className="text-5xl mb-4">😿</div>
              <h3 className="text-xl font-bold text-gray-800 mb-2">噢不，魔法失效了</h3>
              <p className="text-gray-600 mb-6">{errorMsg}</p>
              <button 
                onClick={resetApp}
                className="px-6 py-2 bg-emerald-500 text-white rounded-full font-bold hover:bg-emerald-600 transition-colors"
              >
                再試一次
              </button>
            </div>
          )}
        </main>

        <footer className="text-center text-emerald-800/40 text-sm mt-20 font-medium">
          <p>© {new Date().getFullYear()} GhibliTrip AI. Powered by Google Gemini.</p>
        </footer>
      </div>
    </div>
  );
};

export default App;

