import { GoogleGenAI, Type } from "@google/genai";
import { TripFormData, ItineraryResult, DayPlan } from "../types";

// Initialize the client. 
// NOTE: Process.env.API_KEY is handled by the runtime environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates the text-based itinerary using Gemini 3 Pro.
 */
export const generateItinerary = async (formData: TripFormData): Promise<ItineraryResult> => {
  const prompt = `
    Create a detailed travel itinerary for a trip to ${formData.destination}.

    Details:
    - Duration: ${formData.days} days
    - Travelers: ${formData.travelers} people
    - Date: Starting ${formData.startDate}
    - Interests/Attractions: ${formData.interests}
    - Food Preferences: ${formData.foodPreferences}
    - Accommodation Style: ${formData.accommodation}
    - Transportation Preference: ${formData.transportation}

    Please provide a structured response with a catchy title, a brief summary, and a day-by-day breakdown including times, specific locations, and descriptions.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "A creative title for the trip" },
          summary: { type: Type.STRING, description: "A short, exciting summary of the trip vibe" },
          days: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.INTEGER },
                theme: { type: Type.STRING, description: "Theme of the day (e.g., Historical Walk)" },
                activities: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING, description: "e.g., 09:00 AM" },
                      activity: { type: Type.STRING, description: "Name of the activity or place" },
                      description: { type: Type.STRING, description: "What to do there, practical tips" },
                      location: { type: Type.STRING, description: "Specific location or area" },
                      costEstimate: { type: Type.STRING, description: "Estimated cost per person" }
                    },
                    required: ["time", "activity", "description", "location"]
                  }
                }
              },
              required: ["day", "theme", "activities"]
            }
          }
        },
        required: ["title", "summary", "days"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No itinerary generated.");

  return JSON.parse(text) as ItineraryResult;
};

/**
 * Generates a Studio Ghibli x Manga style map for a specific day using Gemini 3 Pro Image.
 */
export const generateDayMap = async (destination: string, dayPlan: DayPlan): Promise<string> => {
  // Extract key locations to avoid overcrowding the prompt, limit to top 5 unique locations
  const locations = Array.from(new Set(dayPlan.activities.map(a => a.location))).slice(0, 5).join(', ');
  const activities = dayPlan.activities.map(a => a.activity).slice(0, 4).join(', ');

  const imagePrompt = `
    Draw a cute, illustrated travel route map for Day ${dayPlan.day} of a trip to ${destination}.

    **Art Style Requirements:**
    - Mix of Japanese Manga style and Studio Ghibli background art (Kazuo Oga style).
    - Hand-drawn watercolor and gouache textures.
    - Vibrant, lush greens, blue skies, warm sunlight.
    - Whimsical, cozy atmosphere.

    **Map Content:**
    - Visualizing the route for these specific locations: ${locations}.
    - Include cute miniature illustrations of the landmarks: ${activities}.
    - Add tiny transportation elements (cute buses, trains, or walking figures) connecting the spots.

    **Text Requirements (CRITICAL):**
    - You MUST label the main locations using **Traditional Chinese (繁體中文)** characters.
    - Do NOT use English labels.
    - The font should look hand-written or like a manga sound effect font.

    **Composition:**
    - A clear, fun map layout (isometric or top-down view).
    - High resolution, detailed, 4k.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { text: imagePrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9",
        imageSize: "1K" 
      }
    }
  });

  // Extract the image from the response parts
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image generated.");
};

import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import HeroInput from './components/HeroInput';
import ItineraryDisplay from './components/ItineraryDisplay';
import { generateItinerary, generateDayMap } from './services/geminiService';
import { TripFormData, ItineraryResult, AppState } from './types';
import { CloudSun } from 'lucide-react';

// 與 HeroInput 使用相同的圖片常數，確保視覺一致性
const LOGO_IMAGE_URL = "https://images.fanpop.com/images/image_uploads/Totoro-my-neighbor-totoro-696264_1024_768.jpg";
// 飛機圖示 (使用卡通風格飛機模擬旅遊氛圍)
const PLANE_IMAGE_URL = "https://cdn-icons-png.flaticon.com/512/2200/2200326.png"; 

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.INPUT);
  const [itinerary, setItinerary] = useState<ItineraryResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Track which days are currently loading their maps
  const [loadingMaps, setLoadingMaps] = useState<number[]>([]);

  const handleFormSubmit = async (data: TripFormData) => {
    setAppState(AppState.GENERATING);
    setErrorMsg(null);
    setItinerary(null);
    setLoadingMaps([]);

    try {
      // Step 1: Generate Text Itinerary
      const result = await generateItinerary(data);
      setItinerary(result);
      setAppState(AppState.RESULT);

      // Step 2: Trigger Map Generation for EACH day
      // We do this without awaiting so the UI shows the text immediately
      const daysIndices = result.days.map(d => d.day);
      setLoadingMaps(daysIndices);

      // Process map generation in parallel
      result.days.forEach(async (dayPlan, index) => {
        try {
          const mapUrl = await generateDayMap(data.destination, dayPlan);

          // Update the specific day with the new map URL
          setItinerary(current => {
            if (!current) return null;
            const newDays = [...current.days];
            newDays[index] = { ...newDays[index], mapUrl: mapUrl };
            return { ...current, days: newDays };
          });

        } catch (err) {
          console.error(`Failed to generate map for day ${dayPlan.day}`, err);
        } finally {
           // Remove from loading state
           setLoadingMaps(prev => prev.filter(d => d !== dayPlan.day));
        }
      });

    } catch (err: any) {
      console.error("Itinerary generation failed", err);
      setErrorMsg(err.message || "發生錯誤，請稍後再試。");
      setAppState(AppState.ERROR);
    }
  };

  const resetApp = () => {
    setAppState(AppState.INPUT);
    setItinerary(null);
    setErrorMsg(null);
    setLoadingMaps([]);
  };

  return (
    <div className="min-h-screen bg-[#f0f9f6] text-gray-800 font-sans selection:bg-emerald-200 selection:text-emerald-900 overflow-x-hidden">

