import { GoogleGenAI, Type } from "@google/genai";
import { TripFormData, ItineraryResult, DayPlan } from "../types";

// Initialize the client. 
// NOTE: Process.env.API_KEY is handled by the runtime environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates the text-based itinerary using Gemini 3 Pro.
 */
export const generateItinerary = async (formData: TripFormData): Promise<ItineraryResult> => {
  const prompt = `
    請為前往 ${formData.destination} 的旅行制定一份詳細的行程表。

    詳細資訊：
    - 天數：${formData.days} 天
    - 人數：${formData.travelers} 人
    - 出發日期：${formData.startDate}
    - 興趣/景點：${formData.interests}
    - 美食偏好：${formData.foodPreferences}
    - 住宿風格：${formData.accommodation}
    - 交通方式：${formData.transportation}

    **重要規則：**
    1. **所有輸出內容必須使用「繁體中文 (Traditional Chinese)」**。
    2. 請提供一個吸引人的標題、簡短的行程摘要。
    3. 每日行程需包含時間、具體地點名稱、活動說明及預算估算。
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "旅行的創意標題 (繁體中文)" },
          summary: { type: Type.STRING, description: "行程摘要與氛圍描述 (繁體中文)" },
          days: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.INTEGER },
                theme: { type: Type.STRING, description: "當日主題 (例如：古都漫步) (繁體中文)" },
                activities: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING, description: "時間 (例如：09:00)" },
                      activity: { type: Type.STRING, description: "活動或地點名稱 (繁體中文)" },
                      description: { type: Type.STRING, description: "活動內容、實用建議 (繁體中文)" },
                      location: { type: Type.STRING, description: "具體地點/區域 (繁體中文)" },
                      costEstimate: { type: Type.STRING, description: "預估費用 (例如：500 TWD)" }
                    },
                    required: ["time", "activity", "description", "location"]
                  }
                }
              },
              required: ["day", "theme", "activities"]
            }
          }
        },
        required: ["title", "summary", "days"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No itinerary generated.");

  return JSON.parse(text) as ItineraryResult;
};

/**
 * Generates a Studio Ghibli x Manga style map for a specific day using Gemini 3 Pro Image.
 */
export const generateDayMap = async (destination: string, dayPlan: DayPlan): Promise<string> => {
  // Extract key locations to avoid overcrowding the prompt, limit to top 4 unique locations for clarity
  const locations = Array.from(new Set(dayPlan.activities.map(a => a.location))).slice(0, 4).join(', ');
  const activities = dayPlan.activities.map(a => a.activity).slice(0, 4).join(', ');

  const imagePrompt = `
    Draw an "Illustrated Tourist Map" for Day ${dayPlan.day} of a trip to ${destination}.

    **Visual Style:**
    - **Studio Ghibli Background Style:** Hand-painted watercolor aesthetics, lush greens, fluffy clouds, warm sunlight, charming details (Kazuo Oga style).
    - **Japanese Manga Elements:** Clean lines, cute miniature buildings.

    **Map Content (Major Locations):**
    - Focus on illustrating these specific major landmarks/locations: ${locations}.
    - Do NOT draw a complex road network. Focus on the *landmarks* placed artistically on a map background.
    - Include cute miniature icons representing the activities: ${activities}.
    - Add whimsical elements like a tiny Catbus, spirits, or travelers walking between spots.

    **Text Labels (CRITICAL):**
    - **MUST USE TRADITIONAL CHINESE (繁體中文)** for the location labels.
    - The text should look like hand-written notes or manga sound effects.
    - Ensure text is legible.

    **Composition:**
    - Top-down or isometric view of the area.
    - Vibrant, colorful, and inviting.
    - High resolution, 4k.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { text: imagePrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9",
        imageSize: "1K" 
      }
    }
  });

  // Extract the image from the response parts
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image generated.");
};

