```typescript
export const generateDayMap = async (day: number, theme: string, activities: string[], destination: string, variant: number = 0): Promise<string> => {
  // Construct a route string from the main activities
  const routeDescription = activities.join(' -> ');

  const prompt = `
    Create a charming, hand-drawn illustrated travel guide map for a specific day trip in ${destination}.

    The map should be a beautiful, whimsical sketchbook page inspired by Studio Ghibli. It should have watercolor textures, soft pastel colors, and an isometric (top-down) perspective. The style is inspired by Studio Ghibli, mixed with travel journal elements.
    The day of the trip is day ${day}. The theme of this trip is "${theme}". The primary activities for this trip are: ${routeDescription}.

    Emphasize hand-drawn elements, such as:
    - Illustrated landmarks or locations tied to the theme and activities.
    - A visible dotted line or whimsical footprints clearly showing the journey's flow.
    - Hand-written text for location names.
    - Add variation ${variant}.

    Provide a visual description of the map to generate.

  `;

  try {
    const result = await fetch('/api/generate-image', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        prompt: prompt,
      }),
    });

    if (!result.ok) {
      throw new Error(`Failed to generate image: ${result.status} ${result.statusText}`);
    }

    const data = await result.json();
    return data.image_url;
  } catch (error) {
    console.error('Error generating image:', error);
    return Promise.reject(error);
  }
};
