import { GoogleGenAI, Type } from "@google/genai";
import { TripFormData, ItineraryResult, DayPlan } from "../types";

// Initialize the client. 
// NOTE: Process.env.API_KEY is handled by the runtime environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates the text-based itinerary using Gemini 3 Pro.
 */
export const generateItinerary = async (formData: TripFormData): Promise<ItineraryResult> => {
  const prompt = `
    請以「資深日本在地導遊」的身分，為前往 ${formData.destination} 的旅行制定一份深度且道地的行程表。

    詳細資訊：
    - 天數：${formData.days} 天
    - 人數：${formData.travelers} 人
    - 出發日期：${formData.startDate}
    - 興趣/景點：${formData.interests}
    - 美食偏好：${formData.foodPreferences}
    - 住宿風格：${formData.accommodation}
    - 交通方式：${formData.transportation}

    **航班與時間限制 (極重要)：**
    - 出發航班時間：${formData.departureTime}
    - 預計飛行時間：${formData.flightDuration} 小時
    - 回程航班時間：${formData.returnTime}

    **購物與伴手禮需求：**
    - ${formData.souvenirPreferences ? `使用者想購買：${formData.souvenirPreferences}` : '請推薦當地特色土特產與必買禮品'}

    **核心規劃重點 (請優先考慮)：**
    1. **發掘在地靈魂**：除了必去地標外，請優先穿插**私房景點 (Hidden Gems)**、**私房絕景**或**季節限定的祭典/活動 (Matsuri)** (若日期相符)。
    2. **深度體驗**：根據興趣 "${formData.interests}"，安排能與當地文化互動的體驗 (例如：參拜神社的正確方式、體驗傳統工藝、逛在地市集等)。
    3. **味蕾探險**：根據美食偏好 "${formData.foodPreferences}"，請推薦**在地人愛去的隱藏版美食**、老舖或特色屋台，避免僅列出連鎖觀光餐廳。
    4. **流暢動線**：確保私房景點與主要行程之間的交通動線順暢，將在地體驗自然融入每日行程。

    **規劃規則：**
    1. **第一天行程**：
       - 請計算預計抵達時間 (假設目的地日本時區比出發地快1小時，且需加上入境與交通時間約1.5小時)。
       - **第一天的活動請務必在「預計抵達並完成入境後」才開始**。
    2. **最後一天行程**：
       - **所有活動必須在回程航班起飛前「3小時」結束**，並安排前往機場的交通。
       - 例如：若回程是 15:00，則行程請在 12:00 前結束，並開始前往機場。
    3. **所有輸出內容必須使用「繁體中文 (Traditional Chinese)」**。
    4. 請提供一個吸引人的標題、簡短的行程摘要 (請提及本次行程的獨特亮點)。
    5. 每日行程需包含時間、具體地點名稱、活動說明及預算估算。
       - **活動說明中，若該地點為私房景點或特殊體驗，請特別標註其獨特之處**。
    6. **請額外提供一份「必買土特產及禮品清單」**，請推薦具當地文化特色、老舖限定或具有故事性的商品 (5-8項)，而非一般機場常見禮盒。
    7. **請額外提供一份「必吃美食清單」**，推薦具當地特色、隱藏版美食或老舖 (5-8項)，這些可以是具體的菜色名稱或特定名店。
    8. **每個活動請標記類型 (type)**，只能是以下之一：
       - 'sightseeing': 觀光景點、參觀
       - 'food': 用餐、咖啡廳、小吃
       - 'transport': 交通移動、搭車、飛機
       - 'shopping': 購物、逛街
       - 'accommodation': 飯店入住、休息
       - 'other': 其他
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "旅行的創意標題 (繁體中文)" },
          summary: { type: Type.STRING, description: "行程摘要與氛圍描述 (繁體中文)" },
          days: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                day: { type: Type.INTEGER },
                theme: { type: Type.STRING, description: "當日主題 (例如：巷弄散策、祭典巡禮) (繁體中文)" },
                activities: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      time: { type: Type.STRING, description: "時間 (例如：09:00)" },
                      activity: { type: Type.STRING, description: "活動或地點名稱 (繁體中文)" },
                      description: { type: Type.STRING, description: "活動內容、實用建議、私房亮點介紹 (繁體中文)" },
                      location: { type: Type.STRING, description: "具體地點/區域 (繁體中文)" },
                      costEstimate: { type: Type.STRING, description: "預估費用 (例如：500 TWD / 2000 JPY)" },
                      type: { 
                        type: Type.STRING, 
                        description: "活動類型",
                        enum: ["sightseeing", "food", "transport", "shopping", "accommodation", "other"]
                      }
                    },
                    required: ["time", "activity", "description", "location", "type"]
                  }
                }
              },
              required: ["day", "theme", "activities"]
            }
          },
          recommendedSouvenirs: {
            type: Type.ARRAY,
            description: "推薦的土特產與禮品清單 (著重在地限定與特色)",
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING, description: "商品名稱" },
                description: { type: Type.STRING, description: "商品介紹、特色與購買理由" },
                bestPlaceToBuy: { type: Type.STRING, description: "推薦購買地點 (例如：本店、特定市集)" },
                estimatedPrice: { type: Type.STRING, description: "參考價格" }
              },
              required: ["name", "description", "bestPlaceToBuy", "estimatedPrice"]
            }
          },
          recommendedFood: {
            type: Type.ARRAY,
            description: "推薦的必吃美食清單",
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING, description: "美食名稱" },
                description: { type: Type.STRING, description: "口感特色或必吃理由" },
                bestPlaceToEat: { type: Type.STRING, description: "推薦店家或區域" },
                estimatedPrice: { type: Type.STRING, description: "參考價格" }
              },
              required: ["name", "description", "bestPlaceToEat", "estimatedPrice"]
            }
          }
        },
        required: ["title", "summary", "days", "recommendedSouvenirs", "recommendedFood"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No itinerary generated.");

  const result = JSON.parse(text) as ItineraryResult;
  // Inject the user's input destination into the result for later use (e.g., map generation)
  result.destination = formData.destination;

  return result;
};

/**
 * Generates a Japanese Manga style illustration for a specific activity using gemini-2.5-flash-image.
 */
export const generateActivityIllustration = async (activity: string, location: string, description: string): Promise<string> => {
  const prompt = `
    Create a high-quality Japanese anime/manga style illustration.
    Subject: The place "${activity}" located at "${location}".
    Mood: Bright, inviting, detailed, clean lines.
    Details: Anime background art style, vibrant colors.
    Context from itinerary: ${description}.
    Ensure the image is scenic and has a distinct high-quality anime aesthetic. No text in the image.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Failed to generate image");
};

/**
 * Generates a photorealistic travel photo for a specific day.
 * @param variant - A number to encourage variation in the generated image.
 */
export const generateDayMap = async (day: number, theme: string, activities: string[], destination: string, variant: number = 0): Promise<string> => {
  // Use comma to list locations for a photo prompt
  const routeDescription = activities.join(', ');

  const prompt = `
    Create a breathtaking, high-resolution, photorealistic travel photograph for a trip in ${destination}.

    **Context:**
    - **Day Theme:** "${theme}"
    - **Highlights:** ${routeDescription}
    - **Variation:** ${variant}

    **Visual Requirements:**
    - **Style:** Official Tourism Website Photography / National Geographic Style.
    - **Realism:** 100% Photorealistic, 8k resolution, sharp focus, professional color grading, cinematic lighting.
    - **Subject:** A stunning scenic view, streetscape, or architectural shot representing the day's main attraction or atmosphere.
    - **Negative Prompt:** Do NOT create a map, do NOT create a drawing/illustration, NO text, NO labels, NO collage/split screen.
    - **Vibe:** Majestic, inviting, and high-quality.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: "4:3",
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Failed to generate photo");
};

/**
 * Generates a focused transportation route map.
 * @param variant - A number to encourage variation in the generated image.
 */
export const generateTransportationMap = async (day: number, theme: string, activities: string[], destination: string, variant: number = 0): Promise<string> => {
  const routeDescription = activities.join(' -> ');

  const prompt = `
    Create a clean, illustrated transportation route map (Transit Map style) for a day trip in ${destination}.

    **Trip Context:**
    - **Route:** ${routeDescription}.
    - **Variation:** ${variant}.

    **Visual Style & Composition:**
    - **Style:** Minimalist, Japanese tourist map style (clear lines, cute functional icons).
    - **Background:** Light solid color or very subtle grid/terrain pattern. Clean and easy to read.
    - **Routes:** Use THICK, CLEAR COLORED LINES to connect the locations in order. 
      - Use solid lines for trains/subways.
      - Use dashed lines for walking paths.
    - **Nodes:** Use distinct circles or pins for each stop (${activities.join(', ')}). Number them 1, 2, 3...
    - **Icons:** Add small icons representing the mode of transport likely used between points (e.g., a mini train, a bus, a walking figure).
    - **Vibe:** Functional but friendly and cute. Not overly artistic/messy like a watercolor painting; more like a helper map in a brochure.

    **Goal:** Visualizing the movement from A to B to C clearly.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: "4:3",
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Failed to generate transportation map");
};

import React, { useState } from 'react';
import { generateDayMap, generateTransportationMap } from '../services/geminiService';
import { Map, Loader2, Download, Image as ImageIcon, RefreshCw, Train, Camera } from 'lucide-react';
import { DayPlan } from '../types';

interface DayMapGeneratorProps {
  dayPlan: DayPlan;
  destination: string;
}

type MapType = 'scenic' | 'transport';

const DayMapGenerator: React.FC<DayMapGeneratorProps> = ({ dayPlan, destination }) => {
  const [activeTab, setActiveTab] = useState<MapType>('scenic');

  const [scenicMapUrl, setScenicMapUrl] = useState<string | null>(null);
  const [transportMapUrl, setTransportMapUrl] = useState<string | null>(null);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [scenicVariant, setScenicVariant] = useState(0);
  const [transportVariant, setTransportVariant] = useState(0);

  const handleGenerateMap = async (type: MapType) => {
    setIsLoading(true);
    setError(null);
    try {
      // Extract main activities (sightseeing/food/shopping/transport)
      const mainActivities = dayPlan.activities
        .filter(a => ['sightseeing', 'food', 'shopping', 'transport'].includes(a.type))
        .map(a => a.activity);

      const limitedActivities = mainActivities.slice(0, 5);

      if (type === 'scenic') {
        const newVariant = scenicVariant + 1;
        setScenicVariant(newVariant);
        const url = await generateDayMap(dayPlan.day, dayPlan.theme, limitedActivities, destination, newVariant);
        setScenicMapUrl(url);
      } else {
        const newVariant = transportVariant + 1;
        setTransportVariant(newVariant);
        const url = await generateTransportationMap(dayPlan.day, dayPlan.theme, limitedActivities, destination, newVariant);
        setTransportMapUrl(url);
      }
    } catch (err) {
      console.error(err);
      setError("圖片生成失敗，請稍後再試");
    } finally {
      setIsLoading(false);
    }
  };

  const currentMapUrl = activeTab === 'scenic' ? scenicMapUrl : transportMapUrl;

  const handleDownload = () => {
    if (!currentMapUrl) return;
    const link = document.createElement('a');
    link.href = currentMapUrl;
    link.download = `Day${dayPlan.day}_${activeTab}Image_${destination}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="mt-6 border-t border-emerald-100 pt-6">

      {/* Tabs */}
      <div className="flex justify-center mb-6">
        <div className="bg-emerald-50/50 p-1 rounded-full border border-emerald-100 flex gap-1">
          <button
            onClick={() => setActiveTab('scenic')}
            className={`px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 transition-all ${
              activeTab === 'scenic' 
                ? 'bg-emerald-600 text-white shadow-md' 
                : 'text-emerald-700 hover:bg-emerald-100'
            }`}
          >
            <Camera className="w-4 h-4" />
            精選景點美照
          </button>
          <button
            onClick={() => setActiveTab('transport')}
            className={`px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 transition-all ${
              activeTab === 'transport' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'text-blue-700 hover:bg-blue-50'
            }`}
          >
            <Train className="w-4 h-4" />
            交通路線地圖
          </button>
        </div>
      </div>

      {!currentMapUrl ? (
        <div className={`flex flex-col items-center justify-center p-6 rounded-2xl border border-dashed transition-colors ${
          activeTab === 'scenic' 
            ? 'bg-emerald-50/30 border-emerald-200' 
            : 'bg-blue-50/30 border-blue-200'
        }`}>
           <h4 className={`font-bold mb-2 flex items-center gap-2 ${activeTab === 'scenic' ? 'text-emerald-800' : 'text-blue-800'}`}>
             {activeTab === 'scenic' ? <Camera className="w-5 h-5" /> : <Train className="w-5 h-5" />}
             {activeTab === 'scenic' ? 'AI 景點美照生成' : 'AI 交通路線圖繪製'}
           </h4>
           <p className="text-sm text-gray-500 mb-4 text-center max-w-sm">
             {activeTab === 'scenic' 
               ? '生成一張代表今日行程的精美實景風格照片，如同官方宣傳照般迷人。' 
               : '產生今日行程的交通動線示意圖，標示車站與轉乘點，讓移動更清晰。'}
           </p>

           {isLoading ? (
             <div className="flex items-center gap-2 px-6 py-3 bg-white rounded-full shadow-sm font-medium text-gray-600">
               <Loader2 className="w-5 h-5 animate-spin" />
               正在生成中...
             </div>
           ) : (
             <button 
               onClick={() => handleGenerateMap(activeTab)}
               className={`flex items-center gap-2 px-6 py-2.5 text-white rounded-full font-bold shadow-md hover:shadow-lg transition-all active:scale-95 ${
                 activeTab === 'scenic' 
                   ? 'bg-emerald-600 hover:bg-emerald-700' 
                   : 'bg-blue-600 hover:bg-blue-700'
               }`}
             >
               {activeTab === 'scenic' ? <Camera className="w-5 h-5" /> : <Train className="w-5 h-5" />}
               {activeTab === 'scenic' ? '生成景點美照' : '繪製交通路線圖'}
             </button>
           )}

           {error && <p className="text-red-500 text-sm mt-3">{error}</p>}
        </div>
      ) : (
        <div className={`bg-white p-4 rounded-2xl shadow-md border animate-fade-in ${
           activeTab === 'scenic' ? 'border-emerald-100' : 'border-blue-100'
        }`}>
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-3">
             <h4 className="font-bold text-gray-800 flex items-center gap-2">
                {activeTab === 'scenic' ? <Camera className="w-5 h-5 text-emerald-600" /> : <Train className="w-5 h-5 text-blue-600" />}
                Day {dayPlan.day} {activeTab === 'scenic' ? '精選景點美照' : '交通路線地圖'}
             </h4>
             <div className="flex gap-2 w-full sm:w-auto">
               <button 
                 onClick={() => handleGenerateMap(activeTab)}
                 disabled={isLoading}
                 className="flex-1 sm:flex-none justify-center flex items-center gap-1.5 px-3 py-1.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                 title="重新生成"
               >
                 <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
                 {isLoading ? '處理中' : '重新生成'}
               </button>
               <button 
                 onClick={handleDownload}
                 disabled={isLoading}
                 className={`flex-1 sm:flex-none justify-center flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-bold transition-colors disabled:opacity-50 ${
                   activeTab === 'scenic'
                     ? 'bg-emerald-100 hover:bg-emerald-200 text-emerald-800'
                     : 'bg-blue-100 hover:bg-blue-200 text-blue-800'
                 }`}
               >
                 <Download className="w-4 h-4" />
                 儲存
               </button>
             </div>
          </div>

          <div className="relative rounded-xl overflow-hidden border border-gray-200 shadow-inner group bg-gray-50 min-h-[200px]">
            {isLoading && (
               <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] flex flex-col items-center justify-center z-10 transition-all">
                  <div className="bg-white p-4 rounded-full shadow-xl">
                    <Loader2 className={`w-8 h-8 animate-spin ${activeTab === 'scenic' ? 'text-emerald-500' : 'text-blue-500'}`} />
                  </div>
                  <p className="mt-4 text-gray-800 font-bold bg-white/80 px-3 py-1 rounded-lg">正在為您重新生成...</p>
               </div>
            )}
            <img 
              src={currentMapUrl} 
              alt={`Day ${dayPlan.day} ${activeTab} Image`} 
              className="w-full h-auto object-cover max-h-[500px]" 
            />
            {/* Overlay hint only when not loading */}
            {!isLoading && <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors pointer-events-none" />}
          </div>
          <p className="text-xs text-center text-gray-400 mt-2">
             {activeTab === 'scenic' ? '* AI 生成照片僅供情境參考，非現場實拍' : '* AI 生成地圖僅供視覺參考，非精確導航地圖'}
          </p>
        </div>
      )}
    </div>
  );
};

