const HeroInput: React.FC<HeroInputProps> = ({ onSubmit, isLoading }) => {
  const [formData, setFormData] = useState<TripFormData>({
    destination: '',
    days: 5,
    travelers: 3,
    startDate: new Date(Date.now() + 20 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    interests: '',
    foodPreferences: '',
