                                        {style.icon} {act.time}
                                    </span>
                                    <h4 className="text-xl font-bold text-gray-800">{act.activity}</h4>
                                </div>
                                <div className="flex items-start text-sm text-gray-500 mb-3 ml-1">
                                    <MapPin className="w-3.5 h-3.5 mt-0.5 mr-1 shrink-0 text-red-400" />
