              <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-red-100 rounded-full"><Utensils className="w-8 h-8 text-red-600" /></div>
                <div>
                  <h3 className="text-2xl font-bold text-red-800 font-serif">必吃美食清單</h3>
