import React, { useEffect, useState } from 'react';
import { Map, ExternalLink, Loader2 } from 'lucide-react';
import { DayPlan } from '../types';
import QRCode from 'qrcode';
import { formatForMaps } from '../utils/helpers';

interface DayMapGeneratorProps {
  dayPlan: DayPlan;
  destination: string;
}

const DayMapGenerator: React.FC<DayMapGeneratorProps> = ({ dayPlan, destination }) => {
  const [mapData, setMapData] = useState<{ stops: string[], mapUrl: string, qrCodeUrl: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const generate = async () => {
        setIsLoading(true);
        // Filter activities
        const activities = dayPlan.activities.filter(act => act.type !== 'transport');

        // Create stops array, including the destination
        const stops = activities.map(act => {
            if (act.geo) {
                return `${act.geo.latitude},${act.geo.longitude}`;
            } else {
                return formatForMaps(act.place);
            }
        });

        // Add the destination as the last stop
        const formattedDestination = formatForMaps(destination);
        stops.push(formattedDestination);

        // Construct the Google Maps URL
        const mapUrl = `https://www.google.com/maps/dir/?api=1&origin=${stops[0]}&destination=${stops[stops.length - 1]}&waypoints=${stops.slice(1, stops.length - 1).join('|')}`;

        try {
            const qrCodeUrl = await QRCode.toDataURL(mapUrl);
            setMapData({ stops, mapUrl, qrCodeUrl });
        } catch (error) {
            console.error("Error generating QR code:", error);
            setMapData({stops, mapUrl, qrCodeUrl: ''});
        } finally {
            setIsLoading(false);
        }
    };

    if (dayPlan) {
        generate();
    }
}, [dayPlan, destination]);

  if (isLoading) {
    return <div className="flex justify-center items-center h-full"><Loader2 className="animate-spin" size={48} /></div>;
  }

  if (!mapData) {
    return null;
  }

  return (
    <div className="flex flex-col items-center gap-4">
      <h2 className="text-xl font-bold">Day Map</h2>
      {mapData.qrCodeUrl ? (
        <a href={mapData.mapUrl} target="_blank" rel="noopener noreferrer" className="flex flex-col items-center gap-2">
          <img src={mapData.qrCodeUrl} alt="QR Code for Google Maps" className="w-64 h-64 border-2 border-gray-300" />
          <p>Scan to Open in Google Maps</p>
          <ExternalLink />
        </a>
      ) : (
        <p>Could not generate QR code.</p>
      )}
    </div>
  );
};

export default DayMapGenerator;
```


