/**
 * Finds official website and real image URL using Google Search Grounding.
 */
export const findLocationInfo = async (activity: string, location: string): Promise<{ imageUrl?: string, officialSite?: string }> => {
  const prompt = `
    Find information for the location: "${location}" related to "${activity}".
    I need two things:
    1. The URL of the official website (or a highly relevant travel guide URL if official site is missing).
    2. A direct URL to a representative, high-quality photo of this place (jpg/png).

    Return the result in JSON format:
    {
      "officialSite": "url_here",
      "imageUrl": "image_url_here"
    }
    If you cannot find a direct image URL, leave "imageUrl" empty string.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json"
    }
  });

  const text = response.text;
  if (!text) return {};

  try {
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse location info JSON", e);
    return {};
  }
};

