  const getGoogleImageSearchUrl = () => {
      const query = encodeURIComponent(`${location} ${activity} photo`);
      return `https://www.google.com/search?tbm=isch&q=${query}`;
  };

  const getGoogleSearchUrl = () => {
      // Changed from "官方網站" to "旅遊介紹" for broader results if fallback is needed
      const query = encodeURIComponent(`${location} 旅遊介紹`);
      return `https://www.google.com/search?q=${query}`;
  };

  if (data) {
    return (
      <div className="mt-4 animate-fade-in space-y-3">
