                <ImageOff className="w-8 h-8 opacity-30" />
                <span className="text-sm">無法預覽圖片 (可能受防盜鏈保護)</span>
                <a 
                    href={getGoogleImageSearchUrl()} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="text-xs flex items-center gap-1 bg-white px-3 py-1.5 rounded-full shadow-sm border border-gray-200 text-blue-600 hover:text-blue-800 transition-colors mt-1"
