                >
                    <Globe className="w-4 h-4" />
                    相關旅遊網站
                </a>
            )}
            <a 
                href={getGoogleImageSearchUrl()}
                target="_blank"
                rel="noopener noreferrer"
                className={`flex items-center justify-center gap-2 px-3 py-2 bg-gray-50 text-gray-600 rounded-lg text-sm font-medium border border-gray-200 hover:bg-gray-100 transition-colors ${!data.officialSite ? 'flex-1' : ''}`}
