        {error && (
             <div className="text-red-500 text-xs flex items-center mt-2 px-2">
                ⚠️ 搜尋超時或無結果
                <a href={getGoogleSearchUrl()} target="_blank" rel="noopener noreferrer" className="ml-2 underline hover:text-red-700">直接 Google</a>
             </div>
        )}
    </div>
  );
};

