                      className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105" 
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-emerald-900/60 to-transparent flex flex-col justify-end p-6 text-left">
                       <span className="text-emerald-200 text-xs font-bold tracking-widest uppercase mb-1 bg-black/20 backdrop-blur w-fit px-2 py-1 rounded">Travel Map Art</span>
                       <h2 className="text-2xl md:text-3xl font-serif font-bold text-white drop-shadow-lg">{itinerary.title}</h2>
                    </div>
                  </>
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]">
                     {isMapLoading ? (
                       <div className="flex flex-col items-center text-emerald-600">
                          <Loader2 className="w-10 h-10 animate-spin mb-3" />
                          <span className="font-medium">AI 正在繪製吉卜力風格行程地圖...</span>
                          <span className="text-xs text-emerald-500 mt-1">標註景點與路線中</span>
                       </div>
                     ) : (
                       <div className="text-center">
                          <h3 className="text-emerald-800 font-bold text-xl mb-3">視覺化您的夢幻旅程</h3>
                          <button 
                            onClick={handleGenerateMap}
                            className="flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-emerald-500 to-teal-500 text-white rounded-full font-bold shadow-lg hover:shadow-emerald-200/50 hover:scale-105 transition-all"
                          >
                            <Map className="w-5 h-5" />
                            生成吉卜力風格旅遊地圖
                          </button>
                          <p className="text-xs text-emerald-600/60 mt-3">包含主要景點路線與繁體中文標示</p>
                       </div>
                     )}
                  </div>
                )}
              </div>

              {/* Default Title */}
              {(!mapImage) && (
                <div className="mb-6">
                  {itinerary.destination && (
                      <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-700 rounded-full text-sm font-medium mb-4">
                        <MapPin className="w-3.5 h-3.5" />
                        {itinerary.destination}
                      </div>
                  )}
                  <h2 className="text-3xl font-bold text-emerald-800 font-serif mb-2 print:block">{itinerary.title}</h2>
                </div>
              )}

              {/* Print Header Logic */}
              <div className={`hidden print:block mb-6 ${mapImage ? 'print:hidden' : ''}`}>
                 <h1 className="text-3xl font-bold text-emerald-800">{itinerary.title}</h1>
                 <div className="text-sm text-gray-500 mt-2">{itinerary.destination} • 園長揪團遊日本</div>
              </div>

              <p className="text-lg text-gray-600 italic leading-relaxed max-w-3xl mx-auto text-left md:text-center">
                {itinerary.summary}
              </p>

              {/* Featured Highlights Gallery */}
              {itinerary.featuredHighlights && itinerary.featuredHighlights.length > 0 && (
                  <FeaturedGallery highlights={itinerary.featuredHighlights} destination={itinerary.destination || itinerary.title} />
              )}

              {/* Special Alerts Section */}
              {itinerary.specialAlerts && itinerary.specialAlerts.length > 0 && (
                 <div className="mt-8 grid gap-4 text-left">
                    {itinerary.specialAlerts.map((alert: TravelAlert, idx) => {
                       const style = ALERT_STYLES[alert.type || 'tip'] || ALERT_STYLES['tip'];
                       return (
                          <div key={idx} className={`p-4 rounded-xl border ${style.bg} ${style.border} flex gap-4 items-start shadow-sm`}>
                             <div className={`p-2 rounded-full bg-white ${style.color} shrink-0`}>
                                {style.icon}
                             </div>
                             <div>
                                <h4 className={`font-bold text-base ${style.color} mb-1 flex items-center gap-2`}>
                                   {alert.title}
                                   {alert.date && <span className="text-xs px-2 py-0.5 rounded-full bg-white/50 border border-current opacity-80">{alert.date}</span>}
                                </h4>
                                <p className={`text-sm opacity-90 text-gray-700`}>{alert.description}</p>
                             </div>
                          </div>
                       );
                    })}
                 </div>
              )}
          </div>
        </div>

        {/* ... rest of the component (List View, Map View, Footer) ... */}
        {/* --- LIST VIEW --- */}
        {viewMode === 'list' && (
          <div className="space-y-8 print:space-y-6">
            {itinerary.days.map((day: DayPlan) => (
              <div key={day.day} className="bg-white/90 rounded-3xl overflow-hidden shadow-xl border border-emerald-100 print:shadow-none print:border print:bg-white">
                <div className="bg-emerald-600 p-4 md:p-6 flex items-center justify-between text-white relative overflow-hidden">
                  <div className="relative z-10 flex flex-1 justify-between items-center">
                      <div>
                        <h3 className="font-bold text-2xl md:text-3xl font-serif">Day {day.day}</h3>
                        <p className="text-emerald-100 font-medium mt-1">{day.theme}</p>
                      </div>
                      <button 
                         onClick={() => handleShareDay(day)}
                         disabled={isExportingStory}
                         className="flex items-center gap-2 bg-white/20 hover:bg-white/30 backdrop-blur-sm px-3 py-2 rounded-lg text-white text-sm font-medium transition-all hover:scale-105 active:scale-95 disabled:opacity-50"
                         title="下載 IG Story 美圖"
                      >
                         {isExportingStory && exportingDay?.day === day.day ? (
                            <Loader2 className="w-5 h-5 animate-spin" />
                         ) : (
                            <Instagram className="w-5 h-5" />
                         )}
                         <span className="hidden sm:inline">Share</span>
                      </button>
                  </div>
                  {/* Decorative circles */}
                  <div className="absolute -right-8 -top-8 w-32 h-32 bg-white opacity-10 rounded-full blur-2xl"></div>
                </div>

                <div className="p-6 md:p-8 relative print:p-4">
                    <div className="absolute left-8 md:left-10 top-8 bottom-8 w-0.5 bg-gray-200"></div>
                    <div className="space-y-8 print:space-y-4">
                      {day.activities.map((act: Activity, idx) => {
                          const style = ACTIVITY_STYLES[act.type || 'other'];
                          const travelStyle = act.travelSuggestion ? (TRAVEL_STYLES[act.travelSuggestion.mode] || TRAVEL_STYLES['other']) : '';

                          // Calculate distance from previous activity
                          let distanceStr = null;
                          if (idx > 0) {
                              const prevAct = day.activities[idx - 1];
                              if (prevAct.geo && act.geo && prevAct.geo.lat && act.geo.lat) {
                                  distanceStr = calculateDistance(prevAct.geo.lat, prevAct.geo.lng, act.geo.lat, act.geo.lng);
                              }
                          }

                          return (
                            <div key={idx} className="relative pl-10 md:pl-12 group print:pl-8">
                                {/* Travel Suggestion Connector */}
                                {act.travelSuggestion && (
                                  <div className="absolute -top-6 left-6 md:left-8 flex flex-col items-start z-10 w-full pr-12">
                                     <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border shadow-sm text-xs transition-colors max-w-full bg-white/95 backdrop-blur ${travelStyle}`}>
                                        <span className="shrink-0">{TRAVEL_ICONS[act.travelSuggestion.mode] || TRAVEL_ICONS['other']}</span>
                                        <span className="font-bold shrink-0">{act.travelSuggestion.duration}</span>
                                        {distanceStr && (
                                            <>
                                                <span className="hidden sm:inline border-l border-current opacity-30 h-3 mx-1"></span>
                                                <span className="font-mono text-emerald-700 font-bold shrink-0">約 {distanceStr}</span>
                                            </>
                                        )}
                                        <span className="hidden sm:inline border-l border-current opacity-30 h-3 mx-1"></span>
                                        <span className="hidden sm:inline truncate opacity-90">{act.travelSuggestion.details}</span>
                                        {act.travelSuggestion.rushHourWarning && (
                                          <span className="flex items-center gap-1 text-red-600 font-bold bg-red-50 px-2 py-0.5 rounded-full border border-red-100 ml-1 shrink-0 animate-pulse">
                                            <AlertTriangle className="w-3.5 h-3.5" />
                                            <span className="hidden sm:inline">尖峰時段</span>
                                          </span>
                                        )}
                                     </div>
                                     {/* Mobile only detail view */}
                                     <div className="sm:hidden text-[10px] text-gray-500 bg-white/80 px-2 py-0.5 rounded mt-1 ml-1 truncate max-w-[200px] shadow-sm border border-gray-100">
                                        {act.travelSuggestion.details}
                                     </div>
                                  </div>
                                )}

                                <div className={`absolute left-2 md:left-4 top-2 w-4 h-4 rounded-full bg-white ring-[3px] ${style.ring}`}>
                                  <div className={`w-full h-full rounded-full opacity-60 ${style.bg.replace('bg-', 'bg-')}`}></div>
                                </div>
                                <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 mb-2">
                                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-sm font-bold font-mono border ${style.bg} ${style.color} ${style.border}`}>
                                        {style.icon} {act.time}
                                    </span>
                                    <h4 className="text-xl font-bold text-gray-800">{act.activity}</h4>
                                </div>
                                <div className="flex items-start text-sm text-gray-500 mb-3 ml-1">
                                    <MapPin className="w-3.5 h-3.5 mt-0.5 mr-1 shrink-0 text-red-400" />
                                    {act.location}
                                </div>
                                <div className={`p-4 rounded-xl border ${style.bg} ${style.border} bg-opacity-40`}>
                                  <p className="text-gray-700 text-sm leading-relaxed">{act.description}</p>
                                  <div className="print:hidden">
                                    {['sightseeing', 'food', 'accommodation', 'shopping'].includes(act.type) && (
                                      <ActivityIllustration activity={act.activity} location={act.location} description={act.description} />
                                    )}
                                  </div>
                                </div>
                            </div>
                          );
                      })}
                    </div>
                    <div className="print:hidden">
                      <DayMapGenerator dayPlan={day} destination={itinerary.destination || itinerary.title} />
                    </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* --- MAP VIEW --- */}
        {viewMode === 'map' && (
          <div className="bg-white rounded-3xl overflow-hidden shadow-xl border border-emerald-100 p-1 animate-fade-in">
            <div className="bg-emerald-50 p-4 border-b border-emerald-100 flex items-center justify-between">
              <h3 className="font-bold text-emerald-800 flex items-center gap-2">
                <Map className="w-5 h-5" />
                行程地圖總覽
              </h3>
              <span className="text-xs text-emerald-600 bg-white px-2 py-1 rounded-md border border-emerald-200">
                {itinerary.days.length} 天行程 • {itinerary.days.reduce((acc, d) => acc + d.activities.filter(a => a.geo).length, 0)} 個景點
              </span>
            </div>
            <div className="p-4">
               <TripMap itinerary={itinerary} />
               <div className="mt-4 flex flex-wrap gap-2 justify-center">
                  {itinerary.days.map((day) => (
                    <div key={day.day} className="flex items-center gap-1.5 text-xs font-medium bg-gray-50 px-2 py-1 rounded-full border border-gray-100">
                      <div 
                        className="w-3 h-3 rounded-full" 
                        style={{ backgroundColor: DAY_COLORS[(day.day - 1) % DAY_COLORS.length] }}
                      ></div>
                      Day {day.day}
                    </div>
                  ))}
               </div>
            </div>
          </div>
        )}

        {/* Footer Lists */}
        <div className={`grid md:grid-cols-2 gap-8 mt-12 print:grid-cols-1 ${viewMode === 'map' ? 'hidden' : ''}`}>
          {itinerary.recommendedFood?.length > 0 && (
            <div className="bg-gradient-to-br from-rose-50 to-red-50 rounded-3xl p-8 shadow-lg border border-red-100 flex flex-col h-full print:bg-white">
              <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-red-100 rounded-full"><Utensils className="w-8 h-8 text-red-600" /></div>
                <div>
                  <h3 className="text-2xl font-bold text-red-800 font-serif">必吃美食清單</h3>
                  <p className="text-red-600/80 text-sm">園長精選在地好味道</p>
                </div>
              </div>
              <div className="space-y-4 flex-1">
                {itinerary.recommendedFood.map((item: FoodItem, idx) => (
                  <div key={idx} className="bg-white p-5 rounded-2xl shadow-sm border border-red-100 hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-lg text-gray-800">{item.name}</h4>
                        <span className="text-xs font-mono bg-red-100 text-red-800 px-2 py-1 rounded-full">{item.estimatedPrice}</span>
                    </div>
                    <p className="text-sm text-gray-600 mb-3">{item.description}</p>
                    <div className="flex items-center text-xs text-red-600 font-medium border-t border-red-50 pt-2"><MapPin className="w-3 h-3 mr-1" />推薦店家: {item.bestPlaceToEat}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {itinerary.recommendedSouvenirs?.length > 0 && (
            <div className="bg-gradient-to-br from-amber-50 to-orange-50 rounded-3xl p-8 shadow-lg border border-orange-100 flex flex-col h-full print:bg-white">
              <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-orange-100 rounded-full"><ShoppingBag className="w-8 h-8 text-orange-600" /></div>
                <div>
                  <h3 className="text-2xl font-bold text-orange-800 font-serif">必買伴手禮清單</h3>
                  <p className="text-orange-600/80 text-sm">園長推薦土特產</p>
                </div>
              </div>
              <div className="space-y-4 flex-1">
                {itinerary.recommendedSouvenirs.map((item: SouvenirItem, idx) => (
                  <div key={idx} className="bg-white p-5 rounded-2xl shadow-sm border border-orange-100 hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-lg text-gray-800 flex items-center gap-2"><Gift className="w-4 h-4 text-orange-400" />{item.name}</h4>
                        <span className="text-xs font-mono bg-orange-100 text-orange-800 px-2 py-1 rounded-full">{item.estimatedPrice}</span>
                    </div>
                    <p className="text-sm text-gray-600 mb-3">{item.description}</p>
                    <div className="flex items-center text-xs text-orange-600 font-medium border-t border-orange-50 pt-2"><MapPin className="w-3 h-3 mr-1" />推薦地點: {item.bestPlaceToBuy}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Hidden Container for Story Generation - Positioned off-screen */}
      {exportingDay && (
        <div 
          ref={storyRef}
          style={{ 
             position: 'fixed', 
             top: 0, 
             left: '-9999px', // Off-screen
             width: '1080px', 
             height: '1920px', 
             background: `linear-gradient(135deg, ${DAY_COLORS[(exportingDay.day - 1) % DAY_COLORS.length]} 0%, #ffffff 100%)`,
             zIndex: -1,
             overflow: 'hidden',
             display: 'flex',
             flexDirection: 'column',
             padding: '80px',
             fontFamily: '"Noto Sans TC", sans-serif'
          }}
        >
           {/* Header */}
           <div style={{ marginBottom: '60px', color: 'white' }}>
               <h3 style={{ fontSize: '48px', fontWeight: 'bold', textTransform: 'uppercase', letterSpacing: '0.1em', opacity: 0.9 }}>
                  {itinerary.destination || 'Japan Trip'}
               </h3>
               <h1 style={{ fontSize: '180px', fontWeight: '900', lineHeight: 1, textShadow: '0 10px 30px rgba(0,0,0,0.2)' }}>
                  Day {exportingDay.day}
               </h1>
               <h2 style={{ fontSize: '56px', fontWeight: 'bold', marginTop: '20px' }}>
                  {exportingDay.theme}
               </h2>
           </div>

           {/* Content Card */}
           <div style={{ 
               flex: 1, 
               background: 'rgba(255,255,255,0.92)', 
               borderRadius: '60px', 
               padding: '60px', 
               boxShadow: '0 40px 80px rgba(0,0,0,0.15)',
               display: 'flex',
               flexDirection: 'column',
               gap: '40px'
           }}>
              {exportingDay.activities.slice(0, 8).map((act, i) => (
                  <div key={i} style={{ display: 'flex', gap: '30px', alignItems: 'flex-start' }}>
                      <div style={{ 
                          width: '140px', 
                          fontWeight: 'bold', 
                          fontSize: '32px', 
                          color: DAY_COLORS[(exportingDay.day - 1) % DAY_COLORS.length],
                          fontFamily: 'monospace' 
                      }}>
                          {act.time}
                      </div>
                      <div style={{ flex: 1 }}>
                          <div style={{ fontSize: '36px', fontWeight: 'bold', color: '#1f2937', marginBottom: '8px' }}>
                              {act.activity}
                          </div>
                          {act.type === 'sightseeing' && (
                             <div style={{ fontSize: '24px', color: '#6b7280', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                <span style={{fontSize: '20px'}}>📍</span> {act.location}
                             </div>
                          )}
                      </div>
                  </div>
              ))}
              {exportingDay.activities.length > 8 && (
                 <div style={{ textAlign: 'center', color: '#9ca3af', fontSize: '28px', marginTop: 'auto' }}>
                    And more...
                 </div>
              )}
           </div>

           {/* Footer */}
           <div style={{ marginTop: '60px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: 'rgba(0,0,0,0.4)' }}>
              <div style={{ fontSize: '32px', fontWeight: 'bold' }}>园长揪團遊日本</div>
              <div style={{ fontSize: '24px' }}>AI Planned Itinerary</div>
           </div>
        </div>
      )}

    </div>
  );
};

export default ItineraryDisplay;
